// single-item input: this reads the config, which is the one object the
// settings node emits.
const cfg = $input.first().json || {};

function urls(raw) {
  return String(raw || '')
    .split(/[\s,]+/)
    .map((u) => u.trim())
    .filter(Boolean);
}

const playUrls = urls(cfg.play_urls);
const appleUrls = urls(cfg.appstore_urls);
const perApp = Number(cfg.reviews_per_app) || 40;

const jobs = [];

// Play takes a per-input cap and honours it. Two apps at 15 returned 30.
if (playUrls.length) {
  jobs.push({
    store: 'Google Play',
    dataset_id: 'gd_m6zagkt024uwvvwuyu',
    payload: playUrls.map((u) => ({ url: u, num_of_reviews: perApp, country: cfg.country || 'US' })),
  });
}

// Apple takes the url and nothing else. Asking for num_of_reviews, country,
// days or sort_by is a validation error, so the cap is applied after download.
if (appleUrls.length) {
  jobs.push({
    store: 'App Store',
    dataset_id: 'gd_m734msue16e0adkbit',
    payload: appleUrls.map((u) => ({ url: u })),
  });
}

if (!jobs.length) {
  throw new Error('Put at least one Google Play or App Store URL in Settings.');
}

return jobs.map((j) => ({ json: j }));

// One progress call per store came back. The crawl is only finished when every
// store is, so the statuses are reduced to a single flag the IF can read.
const results = $input.all().map((i) => i.json || {});
const jobs = $('Plan The Crawls').all().map((i) => i.json || {});

const states = results.map((r, i) => ({
  store: (jobs[i] || {}).store || `job ${i + 1}`,
  status: String(r.status || 'unknown'),
  records: Number(r.records) || 0,
}));

const failed = states.filter((s) => s.status === 'failed');
const ready = states.filter((s) => s.status === 'ready');

// $runIndex is the number of times this node has already run, so it is the poll
// count. Without a ceiling a stuck snapshot would spin all night.
const polls = $runIndex + 1;
const giveUp = polls >= (Number($('Settings').first().json.max_polls) || 20);

const allDone = ready.length + failed.length === states.length;

// One item per store, carrying that store's snapshot id. Collapsing this to a
// single item breaks the loop twice over: the next progress call has no id to
// put in its URL and 404s on "/progress/", and the download below pairs on
// $itemIndex, so it would fetch snapshot zero and silently drop every other
// store. Both failures leave every node green.
return states.map((s, i) => ({
  json: {
    ...s,
    snapshot_id: String(
      (results[i] || {}).snapshot_id ||
        ($('Ask Both Stores For Reviews').all()[i] || { json: {} }).json.snapshot_id ||
        ''
    ),
    states,
    all_ready: allDone,
    give_up: giveUp,
    done: allDone || giveUp,
    polls,
    failed_stores: failed.map((f) => f.store),
  },
}));

const cfg = $('Settings').first().json;
const jobs = $('Plan The Crawls').all().map((i) => i.json || {});
const downloads = $input.all().map((i) => i.json);

const cutoff = Date.now() - (Number(cfg.days_back) || 180) * 86400000;
const perApp = Number(cfg.reviews_per_app) || 40;

// The download node hands back one n8n item per review row, not one payload
// per crawl, so an item's position says nothing about which store it came
// from. Every row carries its own store URL, so the store is read off the row.
function storeOf(row) {
  const from = String(row.app_url || row.url || row.review_url || '');
  if (from.indexOf('play.google.com') !== -1) return 'Google Play';
  // The dataset answers on itunes.apple.com even though every App Store URL a
  // human pastes in is apps.apple.com. Matching only the public hostname puts
  // every Apple review in an "unknown store" bucket and leaves the App Store
  // column reading 0 of 0 on a run that downloaded five hundred of them.
  if (from.indexOf('apps.apple.com') !== -1) return 'App Store';
  if (from.indexOf('itunes.apple.com') !== -1) return 'App Store';
  return 'unknown store';
}

// Apple rows carry a numeric app_id and no title, so the readable name has to
// come back from the URL that was configured for the crawl.
const appleNames = new Map();
for (const raw of String(cfg.appstore_urls || '').split(/[\n,]+/)) {
  const m = String(raw).match(/\/app\/([^/]+)\/id(\d+)/);
  if (m) appleNames.set(m[2], m[1].replace(/-/g, ' '));
}

// Play's url is the app page; Apple's url is the review and the app sits in
// app_url. Grouping on the wrong one gives a bucket per review on one store.
// Both stores carry app_title, which reads better in a digest than a package
// id, so that wins when it is there.
function appKey(row) {
  const title = String(row.app_title || '').trim();
  if (title) return title;
  const named = appleNames.get(String(row.app_id || ''));
  if (named) return named;
  const from = String(row.app_url || row.url || '');
  const apple = from.match(/\/app\/([^/]+)\/id(\d+)/);
  if (apple) return apple[1].replace(/-/g, ' ');
  const play = from.match(/[?&]id=([^&#]+)/);
  if (play) return play[1];
  return String(row.app_id || 'unknown app');
}

const reviews = [];
const perStore = {};
const errors = [];

// Every planned store is listed up front, so a store whose crawl came back
// empty reports zero instead of dropping out of the header entirely.
for (const job of jobs) {
  if (job.store) perStore[job.store] = { downloaded: 0, used: 0, errors: 0 };
}

const byStore = new Map();
for (const row of downloads) {
  if (!row || typeof row !== 'object') continue;
  const store = storeOf(row);
  if (!perStore[store]) perStore[store] = { downloaded: 0, used: 0, errors: 0 };
  perStore[store].downloaded += 1;
  const list = byStore.get(store) || [];
  list.push(row);
  byStore.set(store, list);
}

for (const [store, rows] of byStore) {
  // Bright Data puts a failed input in the results array as a row with an
  // error and no review text, and it can be the first one - so the shape of
  // row zero is not the shape of the dataset.
  const clean = [];
  for (const row of rows) {
    if (row.error || row.error_code) {
      perStore[store].errors += 1;
      errors.push(`${store}: ${String(row.error || row.error_code).slice(0, 140)}`);
      continue;
    }
    const text = String(row.review || '').trim();
    if (!text) continue;

    const when = Date.parse(row.review_date || '');
    if (Number.isFinite(when) && when < cutoff) continue;

    clean.push({
      store,
      app: appKey(row),
      review_id: String(row.review_id || ''),
      title: String(row.review_title || ''),
      text,
      rating: Number(row.review_rating) || 0,
      when: Number.isFinite(when) ? new Date(when).toISOString().slice(0, 10) : '',
      when_ms: Number.isFinite(when) ? when : 0,
      // Only Play carries a helpfulness count. Apple rows get 0 rather than a
      // fabricated one, and the ranking treats it as a tie-breaker only.
      helpful: Number(row.found_helpful) || 0,
      link: String(row.review_url || row.url || ''),
    });
  }

  // Apple has no cap of its own, so newest-first then slice is the only way to
  // stop one noisy app from filling the whole report.
  clean.sort((a, b) => b.when_ms - a.when_ms);
  const byApp = new Map();
  for (const r of clean) {
    const list = byApp.get(r.app) || [];
    if (list.length < perApp) {
      list.push(r);
      byApp.set(r.app, list);
    }
  }
  for (const list of byApp.values()) {
    perStore[store].used += list.length;
    reviews.push(...list);
  }
}

return [{ json: { reviews, per_store: perStore, errors, review_count: reviews.length } }];

// single-item input: the merge above emits one object holding every review.
const merged = $input.first().json || {};
const reviews = Array.isArray(merged.reviews) ? merged.reviews : [];

// Rules decide what counts as a request, not the model. Thirty-odd ask-shaped
// phrases, all of which appear in real review prose. Keeping this in code is
// what makes the tally reproducible between runs.
const ASK_PATTERNS = [
  /\bwish(?:es)?\s+(?:it|they|this|there)\b/i,
  /\bi\s+wish\b/i,
  /\bplease\s+(?:add|allow|include|support|bring|make|give|fix)\b/i,
  /\bwould\s+(?:be\s+)?(?:great|nice|love|helpful|amazing|perfect)\s+if\b/i,
  /\bwould\s+love\s+(?:to\s+see|if|a|an|the)\b/i,
  /\b(?:needs?|need)\s+(?:a|an|the|more|better)\b/i,
  /\bno\s+way\s+to\b/i,
  /\bthere\s+is\s+no\s+(?:option|way|setting|support)\b/i,
  /\bdoes(?:n't|\s+not)\s+(?:have|support|allow|let)\b/i,
  /\bcan(?:'t|not)\s+(?:you\s+)?(?:add|export|import|sync|share|print|schedule)\b/i,
  /\bmissing\s+(?:a|an|the|basic)?\s*\w+/i,
  /\bhope\s+(?:they|you)\s+(?:add|bring|make)\b/i,
  /\badd\s+(?:a|an|the)\s+\w+\s+(?:option|feature|button|mode)\b/i,
  /\bif\s+only\s+it\b/i,
  /\blacks?\s+(?:a|an|the|any)\b/i,
  /\bsuggestion\b/i,
  /\bfeature\s+request\b/i,
];

const asks = [];
for (const r of reviews) {
  const haystack = `${r.title} ${r.text}`;
  const hit = ASK_PATTERNS.find((p) => p.test(haystack));
  if (!hit) continue;

  // The sentence carrying the ask is worth more to the model than the whole
  // review, most of which is unrelated praise or a bug report.
  const sentences = String(r.text).split(/(?<=[.!?])\s+/);
  const asking = sentences.find((s) => ASK_PATTERNS.some((p) => p.test(s))) || r.text;

  asks.push({
    ...r,
    ask: asking.trim().slice(0, 300),
    weight: 1 + Math.min(r.helpful, 50) / 25 + (r.rating > 0 && r.rating <= 2 ? 0.5 : 0),
  });
}

// Never return zero items: the branch below has to stay alive so the "nobody
// asked for anything" message can fire.
asks.sort((a, b) => b.weight - a.weight);
const capped = asks.slice(0, Number($('Settings').first().json.max_asks) || 60);

return [{
  json: {
    asks: capped,
    ask_count: asks.length,
    reviewed: reviews.length,
    per_store: merged.per_store || {},
    errors: merged.errors || [],
    brief: capped
      .map((a, i) => `${i + 1}. [${a.app}] ${a.ask}`)
      .join('\n'),
  },
}];

// single-item input: one object carrying every ask.
const found = $('Find The Asks').first().json || {};
const cfg = $('Settings').first().json;
const asks = Array.isArray(found.asks) ? found.asks : [];

let named = '';
try {
  named = String(($input.first().json || {}).text || '');
} catch (e) {
  named = '';
}

// The model is asked for "3. two or three words" and sometimes answers in
// prose. Lines that do not start with a number are dropped rather than
// attached to whichever ask happens to be next in the list.
const featureOf = new Map();
for (const line of named.split('\n')) {
  const m = line.match(/^\s*(\d+)[.)]\s*(.+)$/);
  if (!m) continue;
  const idx = Number(m[1]) - 1;
  if (!asks[idx]) continue;
  const label = m[2].trim().replace(/^["']|["'.]+$/g, '').toLowerCase();
  if (label && label.length < 60) featureOf.set(idx, label);
}

function words(s) {
  return String(s || '')
    .toLowerCase()
    .split(/[^a-z0-9+]+/)
    .filter((w) => w.length > 2);
}

const mine = String(cfg.your_features || '')
  .split(/[,;\n]+/)
  .map((f) => f.trim())
  .filter(Boolean);
const mineTokens = mine.map((f) => ({ label: f, tokens: new Set(words(f)) }));

// A request matches something you ship when most of the feature's words appear
// in one of yours. Token overlap rather than string equality, because "dark
// mode please" and "Dark theme" are the same ask and share nothing exact.
function shipped(label) {
  const t = words(label);
  if (!t.length) return null;
  let best = null;
  for (const f of mineTokens) {
    const hits = t.filter((w) => f.tokens.has(w)).length;
    const score = hits / t.length;
    if (score >= 0.5 && (!best || score > best.score)) best = { label: f.label, score };
  }
  return best;
}

const tally = new Map();
asks.forEach((ask, i) => {
  const label = featureOf.get(i);
  if (!label) return;
  const entry = tally.get(label) || {
    feature: label,
    weight: 0,
    mentions: 0,
    apps: new Set(),
    stores: new Set(),
    quotes: [],
  };
  entry.weight += ask.weight;
  entry.mentions += 1;
  entry.apps.add(ask.app);
  entry.stores.add(ask.store);
  if (entry.quotes.length < 2) entry.quotes.push({ app: ask.app, text: ask.ask, link: ask.link });
  tally.set(label, entry);
});

const features = [...tally.values()]
  .map((e) => {
    const match = shipped(e.feature);
    return {
      feature: e.feature,
      mentions: e.mentions,
      weight: Math.round(e.weight * 10) / 10,
      apps: [...e.apps],
      stores: [...e.stores],
      quotes: e.quotes,
      you_ship_it: Boolean(match),
      your_name_for_it: match ? match.label : '',
      verdict: match ? 'positioning' : 'roadmap',
    };
  })
  .sort((a, b) => b.weight - a.weight || b.mentions - a.mentions);

return [{
  json: {
    features,
    unnamed: asks.length - featureOf.size,
    ask_count: found.ask_count || 0,
    reviewed: found.reviewed || 0,
    per_store: found.per_store || {},
    errors: found.errors || [],
    your_feature_count: mine.length,
  },
}];

// single-item input: the scorer above emits one object.
const scored = $input.first().json || {};
const cfg = $('Settings').first().json;
const features = Array.isArray(scored.features) ? scored.features : [];

function plural(n, one, many) {
  return `${n} ${n === 1 ? one : many}`;
}

const roadmap = features.filter((f) => f.verdict === 'roadmap');
const positioning = features.filter((f) => f.verdict === 'positioning');

const lines = [];
lines.push(`*What users are asking competitor apps for*`);
const stores = Object.entries(scored.per_store || {})
  .map(([s, v]) => `${s}: ${v.used} of ${v.downloaded} reviews used`)
  .join(' | ');
lines.push(`${stores || 'no store data'} - ${plural(scored.ask_count || 0, 'request', 'requests')} found in ${plural(scored.reviewed || 0, 'review', 'reviews')}.`);
if ((scored.errors || []).length) {
  lines.push(`_${plural(scored.errors.length, 'app', 'apps')} could not be crawled: ${scored.errors.slice(0, 2).join('; ')}_`);
}
lines.push('');

lines.push(`*They want it and you do not have it* (${roadmap.length})`);
if (!roadmap.length) {
  lines.push('• Nothing in this pull that you do not already ship.');
}
for (const f of roadmap.slice(0, 6)) {
  lines.push(`• *${f.feature}* - ${plural(f.mentions, 'mention', 'mentions')} across ${f.apps.join(', ')}`);
  if (f.quotes[0]) lines.push(`    "${f.quotes[0].text.slice(0, 160)}"`);
}
lines.push('');

lines.push(`*They want it and you already ship it* (${positioning.length})`);
if (!positioning.length) {
  lines.push('• Nothing asked for matched your feature list.');
}
for (const f of positioning.slice(0, 6)) {
  lines.push(`• *${f.feature}* - you call it "${f.your_name_for_it}", ${plural(f.mentions, 'mention', 'mentions')}`);
}
if (positioning.length) {
  lines.push('_These are the cheap ones. The demand is proven and the work is done; it is your listing and your landing page that have not caught up._');
}

if (scored.unnamed > 0) {
  lines.push('');
  lines.push(`_${plural(scored.unnamed, 'request', 'requests')} could not be named and are in the sheet as raw quotes._`);
}

const rows = [];
for (const f of features) {
  for (const q of f.quotes) {
    rows.push({
      checked_on: new Date().toISOString().slice(0, 10),
      feature: f.feature,
      verdict: f.verdict,
      you_ship_it: f.you_ship_it ? 'yes' : 'no',
      your_name_for_it: f.your_name_for_it,
      mentions: f.mentions,
      weight: f.weight,
      apps: f.apps.join(', '),
      stores: f.stores.join(', '),
      quote: q.text,
      quote_app: q.app,
      link: q.link,
    });
  }
}

// One item per row so the Sheets append writes one row per quote rather than a
// single row whose columns are "message" and "rows".
return [{ json: { message: lines.join('\n'), rows, row_count: rows.length } }];

